import java.util.*;
import java.io.*;
/** Standard-library JSON transport, independent of the backend's credentials and libraries. */
public class JavaRunner {
 static String s;static int p;
 static Object parse(String text){s=text;p=0;return value();}
 static void ws(){while(p<s.length()&&Character.isWhitespace(s.charAt(p)))p++;}
 static Object value(){ws();char c=s.charAt(p);if(c=='['){p++;List<Object>a=new ArrayList<>();ws();if(s.charAt(p)==']'){p++;return a;}do{a.add(value());ws();c=s.charAt(p++);}while(c==',');return a;}if(c=='{'){p++;Map<String,Object>m=new LinkedHashMap<>();ws();if(s.charAt(p)=='}'){p++;return m;}do{String k=(String)value();ws();p++;m.put(k,value());ws();c=s.charAt(p++);}while(c==',');return m;}if(c=='"'){p++;StringBuilder b=new StringBuilder();while((c=s.charAt(p++))!='"'){if(c=='\\'){c=s.charAt(p++);if(c=='u'){c=(char)Integer.parseInt(s.substring(p,p+4),16);p+=4;}else c=switch(c){case 'n'->'\n';case 'r'->'\r';case 't'->'\t';case 'b'->'\b';case 'f'->'\f';default->c;};}b.append(c);}return b.toString();}int start=p;while(p<s.length()&&",]} \n\r\t".indexOf(s.charAt(p))<0)p++;String token=s.substring(start,p);if(token.equals("true"))return true;if(token.equals("false"))return false;if(token.equals("null"))return null;if(token.contains(".")||token.contains("e")||token.contains("E"))return Double.valueOf(token);return Long.valueOf(token);}
 static String json(Object v){if(v==null)return "null";if(v instanceof String t){StringBuilder b=new StringBuilder("\"");for(char c:t.toCharArray())switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}if(v instanceof Map<?,?>m){List<String>a=new ArrayList<>();m.forEach((k,x)->a.add(json(k.toString())+":"+json(x)));return "{"+String.join(",",a)+"}";}if(v instanceof Iterable<?>it){List<String>a=new ArrayList<>();it.forEach(x->a.add(json(x)));return "["+String.join(",",a)+"]";}if(v.getClass().isArray()){List<String>a=new ArrayList<>();for(int i=0;i<java.lang.reflect.Array.getLength(v);i++)a.add(json(java.lang.reflect.Array.get(v,i)));return "["+String.join(",",a)+"]";}if(v instanceof Number||v instanceof Boolean)return v.toString();throw new IllegalArgumentException("Return a JSON-compatible value.");}
 @SuppressWarnings("unchecked") public static void main(String[]args)throws Exception{String input=new String(System.in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);List<Object>tests=(List<Object>)parse(input);List<Object>out=new ArrayList<>();for(Object t:tests)out.add(Solution.solve((List<Object>)t));System.out.write(json(out).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
}
